projects=[dict(id='self-hosted-cicd',title='Self-Hosted CI/CD Pipeline',status='Implemented',category='Infrastructure',desc='From a Git push to a running website. A Linux-based deployment environment with a self-hosted runner, Docker, Nginx, and deployment verification.',tags=['Linux Mint','GitHub Actions','Docker','Nginx','Bash','systemd','SSH'],problem='Create a repeatable path from source control to a self-hosted website without relying on manual file transfers.',solution='GitHub Actions assigns a workflow job to the Linux runner. The runner executes deployment tasks on the host; Docker and Nginx serve the static application.',steps=['Prepare the Linux Mint host and Docker runtime.','Install the GitHub Actions runner as a service under a separate account.','Use the pardo-deploy runner label to target deployment jobs.','Deploy static application assets and verify the HTTP response.'],results='A deployment test completed successfully, as reported by the lab owner. Continuous deployment on every push and public availability have not been independently verified.',lesson='Treat runner permissions, host services, container workloads, and application health as separate concerns.',future=['Review the existing workflow before changing it.','Add structured deployment records and rollback verification.','Connect sanitized, read-only telemetry.']),dict(id='aws-high-availability',title='AWS High-Availability Architecture',status='Documented lab',category='AWS',desc='Exploring application availability through load balancing, Auto Scaling, and deliberate network design.',tags=['Amazon EC2','ALB','Auto Scaling','Amazon VPC','Security Groups'],problem='Understand how an application can distribute traffic and recover capacity across multiple availability zones.',solution='The lab explores an Application Load Balancer in front of EC2 instances managed by an Auto Scaling Group, with VPC networking and security group boundaries.',steps=['Define network boundaries and security groups.','Configure EC2 application capacity.','Explore load balancer target health and scaling policies.'],results='Presented as an educational AWS lab. No continuous production operation, availability percentage, or performance benchmark is claimed.',lesson='Availability depends on application health, network paths, and recovery behavior together.',future=['Publish configuration evidence and diagrams from the lab.','Document failure scenarios and cost tradeoffs.']),dict(id='serverless-task-api',title='Serverless Task API',status='Documented project',category='AWS',desc='An API-driven task application exploring event-driven architecture and managed AWS services.',tags=['AWS Lambda','API Gateway','DynamoDB','IAM'],problem='Explore a task API without managing application servers.',solution='API Gateway receives HTTP requests, Lambda handles application logic, and DynamoDB provides managed persistence. IAM defines service permissions.',steps=['Define request and response contracts.','Connect API routes to Lambda handlers.','Scope database access with IAM.'],results='A project entry for the serverless task API. Public endpoints, test results, and a verified repository link have not been supplied.',lesson='Managed infrastructure still requires careful validation, permission scoping, and error handling.',future=['Add reviewed API examples and repository links.','Publish verified response samples and validation results.']),dict(id='infrastructure-monitoring',title='Infrastructure Monitoring',status='Planned',category='Observability',desc='A future observability layer for infrastructure metrics, service health, and operational awareness.',tags=['Prometheus','Grafana','Linux','Docker'],problem='Make host and application behavior observable through a safe, read-only public interface.',solution='Proposed: a private collector and sanitized server-side API, with dashboards showing only approved operational fields.',steps=['Define a minimal public telemetry schema.','Choose collection and retention policies.','Implement authenticated collection and sanitized read-only delivery.'],results='Planning only. No monitoring stack or live data connection is represented as implemented.',lesson='The public dashboard must stay separate from privileged host administration.',future=['Implement private metric collection.','Add historical charts and health-check evidence.'])]
