def shell(body,title='Cloud Engineering, Linux & Infrastructure',route='/'):
 nav=''.join(f'<a href="{url}" class="{"active" if route==url else ""}" {"aria-current=page" if route==url else ""}>{name}</a>' for name,url in navs)
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pardo Cloud Lab | {title}</title><meta name="description" content="Explore Pardo Cloud Lab, an engineering initiative by Pardo Digital showcasing hands-on Linux infrastructure, Docker, CI/CD, AWS architecture, and cloud automation projects."><meta property="og:title" content="Pardo Cloud Lab — Infrastructure, built in the open."><meta property="og:description" content="Linux, containers, CI/CD, and cloud engineering. An engineering initiative by Pardo Digital."><meta property="og:type" content="website"><meta property="og:image" content="/social-preview.svg"><meta name="theme-color" content="#0757f9"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script><script src="/telemetry.js?v=3" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header><div class="wrap nav"><a class="brand" href="/" aria-label="Pardo Cloud Lab home"><span class="mark">p.</span><span><strong>PARDO CLOUD LAB</strong><small>An engineering initiative by Pardo Digital</small></span></a><nav aria-label="Main navigation" id="navigation">{nav}</nav><a class="github" href="https://github.com/juliopardog/pardo-cloud-lab" target="_blank" rel="noopener">GitHub ↗</a><button class="iconbtn" id="theme" aria-label="Toggle dark mode">◐</button><button class="iconbtn mobile" id="menu" aria-controls="navigation" aria-expanded="false" aria-label="Toggle navigation">☰</button></div></header><main id="main" class="wrap">{body}</main><footer><div class="wrap footer-inner"><div><strong>PARDO CLOUD LAB</strong><br>An engineering initiative by Pardo Digital LLC.<br>© 2026 Pardo Digital LLC.</div><div>Build. Deploy. Observe. Improve.<br><a href="https://github.com/juliopardog">GitHub ↗</a><a href="https://pardodigital.com">Pardo Digital ↗</a><a href="/contact/">Contact</a></div></div></footer><button class="iconbtn backtop" aria-label="Back to top" onclick="window.scrollTo({{top:0,behavior:'smooth'}})">↑</button><dialog id="component-dialog"><button class="iconbtn close" aria-label="Close component details" onclick="this.closest('dialog').close()">×</button><div id="dialog-content"></div></dialog></body></html>'''
def write(route,body,title):
 f=d/route.strip('/')/'index.html' if route!='/' else d/'index.html';f.parent.mkdir(parents=True,exist_ok=True);f.write_text(shell(body,title,route))
def header(eyebrow,title,desc):return f'<div class="page-header"><div class="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{desc}</p></div>'
def art(i):
 nodes=[['git','Actions','Nginx'],['EC2','ALB','ASG'],['API','λ','DB'],['Host','Metrics','Charts']][i]
 return '<div class="card-art" aria-hidden="true">'+'<span class="mini-arrow">→</span>'.join('<span class="mini-node">'+n+'</span>' for n in nodes)+'</div>'
def cards():
 return ''.join(f'''<article class="card" data-category="{x['category']}" data-title="{x['title'].lower()}">{art(i)}<div class="card-content"><div class="card-top"><span class="number">PROJECT / 0{i+1}</span><span class="badge {'planned' if x['status']=='Planned' else 'doc' if i else ''}">{x['status']}</span></div><h3>{x['title']}</h3><p>{x['desc']}</p><div class="tags">{''.join('<span class="tag">'+t+'</span>' for t in x['tags'][:4])}</div><div class="card-footer"><a href="/projects/{x['id']}/">View project <span aria-hidden="true">↗</span></a>{'<a href="https://github.com/juliopardog/pardo-cloud-lab" aria-label="View pipeline repository">GitHub ↗</a>' if i==0 else '<span class="number">'+x['category']+'</span>'}</div></div></article>''' for i,x in enumerate(projects))
